// Stored query results, as the Workbench keeps them (queryStream.ts): a result past 10,000 rows moves to an IndexedDB
// database of its own, named DATABASE_PREFIX + its id and listed in a localStorage registry; smaller results stay in
// the page's memory.
const { expect } = require('@playwright/test');

const DATABASE_PREFIX = 'rdf4j-workbench-row-store:';
const REGISTRY_PREFIX = 'rdf4j.workbench.row-store.v2:';
const MAINTAINED_KEY = 'rdf4j.workbench.row-store.v2.maintained';

/** A query of rows × columns rows that needs no data: enough rows to be stored in IndexedDB. */
function largeQuery(rows = 120, columns = 100) {
	const range = (count) => Array.from({ length: count }, (_, index) => String(index)).join(' ');
	return `SELECT ?a ?b WHERE { VALUES ?a { ${range(rows)} } VALUES ?b { ${range(columns)} } }`;
}

/** The ids of the stored results with a database, and the registry entries, of the page's origin. */
async function storedResults(page) {
	return page.evaluate(async ({ databasePrefix, registryPrefix }) => {
		// A version-0 entry is what an aborted open leaves in WebKit: no store.
		const databases = (await indexedDB.databases())
			.filter((database) => database.version > 0 && database.name && database.name.startsWith(databasePrefix))
			.map((database) => database.name.substring(databasePrefix.length)).sort();
		const registry = {};
		for (let index = 0; index < localStorage.length; index++) {
			const key = localStorage.key(index);
			if (key && key.startsWith(registryPrefix)) {
				registry[key.substring(registryPrefix.length)] = JSON.parse(localStorage.getItem(key));
			}
		}
		return { databases, registry };
	}, { databasePrefix: DATABASE_PREFIX, registryPrefix: REGISTRY_PREFIX });
}

/** Waits for one newly registered result to persist its metadata and all of its physical rows. */
async function waitForStoredResult(page, before, expectedCount) {
	const beforeIds = [...new Set([...before.databases, ...Object.keys(before.registry)])];
	let persisted;
	await expect.poll(async () => {
		persisted = await page.evaluate(async ({ databasePrefix, registryPrefix, beforeIds, expectedCount }) => {
			const previousIds = new Set(beforeIds);
			const registryIds = [];
			for (let index = 0; index < localStorage.length; index++) {
				const key = localStorage.key(index);
				if (key && key.startsWith(registryPrefix)) {
					const id = key.substring(registryPrefix.length);
					if (!previousIds.has(id)) {
						registryIds.push(id);
					}
				}
			}
			if (registryIds.length === 0) {
				return false;
			}
			if (registryIds.length !== 1) {
				throw new Error(`Expected one newly registered stored result, found ${registryIds.length}.`);
			}

			// Exclude every pre-existing result before opening a database. Other tabs may hold their write transactions.
			const id = registryIds[0];
			if (previousIds.has(id)) {
				throw new Error(`Stored result ${id} was present before this query.`);
			}
			const databaseName = databasePrefix + id;
			const listed = (await indexedDB.databases())
				.some(database => database.name === databaseName && database.version > 0);
			if (!listed) {
				return false;
			}

			const persisted = await new Promise((resolve, reject) => {
				const request = indexedDB.open(databaseName);
				let disappearedSinceEnumeration = false;
				let openWasBlocked = false;
				request.onupgradeneeded = (event) => {
					if (event.oldVersion === 0) {
						// The result was deleted since enumeration. Abort instead of recreating an empty database.
						disappearedSinceEnumeration = true;
						request.transaction.abort();
					} else {
						request.transaction.abort();
						reject(new Error(`Stored result ${id} changed versions while being inspected.`));
					}
				};
				request.onerror = () => {
					if (disappearedSinceEnumeration) {
						resolve(null);
					} else {
						reject(request.error || new Error(`Unable to open stored result ${id}.`));
					}
				};
				request.onblocked = () => {
					openWasBlocked = true;
					reject(new Error(`Opening stored result ${id} was blocked.`));
				};
				request.onsuccess = () => {
					const database = request.result;
					if (openWasBlocked) {
						database.close();
						return;
					}
					database.onversionchange = () => database.close();
					if (!database.objectStoreNames.contains('stores') || !database.objectStoreNames.contains('rows')) {
						database.close();
						reject(new Error(`Stored result ${id} has an unexpected database schema.`));
						return;
					}
					let transaction;
					try {
						transaction = database.transaction(['stores', 'rows'], 'readonly');
					} catch (error) {
						database.close();
						reject(error);
						return;
					}
					let metadata;
					let malformedRowBlock = false;
					let physicalBlockCount = 0;
					let physicalRowCount = 0;
					const storeRequest = transaction.objectStore('stores').get(id);
					storeRequest.onsuccess = () => { metadata = storeRequest.result; };
					const rows = transaction.objectStore('rows');
					const cursorRequest = rows.openCursor(IDBKeyRange.bound([id, 0], [id, Number.MAX_SAFE_INTEGER]));
					cursorRequest.onsuccess = () => {
						const cursor = cursorRequest.result;
						if (!cursor) {
							return;
						}
						const blockRows = cursor.value && cursor.value.count;
						if (!Number.isSafeInteger(blockRows) || blockRows <= 0) {
							malformedRowBlock = true;
							transaction.abort();
							return;
						}
						physicalBlockCount++;
						physicalRowCount += blockRows;
						cursor.continue();
					};
					transaction.oncomplete = () => {
						database.close();
						resolve({ id, metadataCount: metadata && metadata.count, physicalBlockCount, physicalRowCount });
					};
					transaction.onerror = transaction.onabort = () => {
						database.close();
						reject(transaction.error || new Error(malformedRowBlock
							? `Stored result ${id} has a malformed physical row block.`
							: `Unable to inspect stored result ${id}.`));
					};
				};
			});
			if (!persisted) {
				return false;
			}
			if (persisted.metadataCount !== undefined
				&& (!Number.isSafeInteger(persisted.metadataCount) || persisted.metadataCount < 0)) {
				throw new Error(`Stored result ${id} has an invalid metadata row count.`);
			}
			if (persisted.metadataCount > expectedCount) {
				throw new Error(
					`Stored result ${id} contains ${persisted.metadataCount} metadata rows; expected ${expectedCount}.`);
			}
			if (persisted.physicalRowCount > expectedCount) {
				throw new Error(
					`Stored result ${id} contains ${persisted.physicalRowCount} physical rows; expected ${expectedCount}.`);
			}
			return persisted.metadataCount === expectedCount
				&& persisted.physicalBlockCount > 0 && persisted.physicalRowCount === expectedCount
				? persisted : false;
		}, { databasePrefix: DATABASE_PREFIX, registryPrefix: REGISTRY_PREFIX, beforeIds, expectedCount });
		return Boolean(persisted);
	}, { timeout: 30000, message: `stored result reaches ${expectedCount} persisted rows` }).toBe(true);
	return persisted;
}

/** Makes the registry say the stores were created and last used at time. */
async function ageStoredResults(page, ids, time) {
	await page.evaluate(({ registryPrefix, ids, time }) => {
		for (const id of ids) {
			const entry = JSON.parse(localStorage.getItem(registryPrefix + id));
			localStorage.setItem(registryPrefix + id, JSON.stringify(Object.assign(entry, { created: time, used: time })));
		}
	}, { registryPrefix: REGISTRY_PREFIX, ids, time });
}

/** A stored result left by a page that ended without disposing it: its database and its registry entry. */
async function plantAbandonedStore(page, id, time) {
	await page.evaluate(({ databasePrefix, registryPrefix, id, time }) => new Promise((resolve, reject) => {
		const request = indexedDB.open(databasePrefix + id, 1);
		request.onupgradeneeded = () => {
			request.result.createObjectStore('stores', { keyPath: 'id' });
			request.result.createObjectStore('rows', { keyPath: ['storeId', 'index'] });
		};
		request.onerror = () => reject(request.error);
		request.onsuccess = () => {
			const database = request.result;
			const transaction = database.transaction(['stores', 'rows'], 'readwrite');
			transaction.objectStore('stores').put({ id, count: 1, format: 'blocks-v2', tailStart: 0, tailRows: 1,
				tailChars: 6, touched: time });
			transaction.objectStore('rows').put({ storeId: id, index: 0, count: 1, text: '[null]' });
			transaction.oncomplete = () => {
				database.close();
				localStorage.setItem(registryPrefix + id, JSON.stringify({ created: time, used: time, bytes: 20 }));
				resolve();
			};
			transaction.onerror = () => reject(transaction.error);
		};
	}), { databasePrefix: DATABASE_PREFIX, registryPrefix: REGISTRY_PREFIX, id, time });
}

/** Lets the next cleanup look at every store, not only those flagged for deletion. */
async function forgetLastCleanup(page) {
	await page.evaluate((key) => localStorage.removeItem(key), MAINTAINED_KEY);
}

module.exports = { DATABASE_PREFIX, REGISTRY_PREFIX, largeQuery, storedResults, ageStoredResults, plantAbandonedStore,
	forgetLastCleanup, waitForStoredResult };
